package app.zhijian.notes;
import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import app.zhijian.notes.data.PaperDb;import app.zhijian.notes.backup.MergePlanner;
import org.json.*;import org.junit.Test;import org.junit.runner.RunWith;import static org.junit.Assert.*;import java.util.UUID;
@RunWith(AndroidJUnit4.class) public class WriteFailureTest {
 private JSONObject note(String title)throws Exception{return new JSONObject().put("title",title).put("mode","markdown").put("content","原始内容").put("tags",new JSONArray());}
 private void failWrites(PaperDb db){db.getWritableDatabase().execSQL("CREATE TEMP TRIGGER ignore_write BEFORE INSERT ON records WHEN NEW.data LIKE '%forced_write_failure%' BEGIN SELECT RAISE(IGNORE); END");}
 @Test public void ignoredSqliteWriteCannotReportSaveSuccess()throws Exception{PaperDb db=new PaperDb(InstrumentationRegistry.getInstrumentation().getTargetContext());JSONObject original=db.snapshot();try{failWrites(db);try{db.save("notes",note("forced_write_failure"));fail("A failed insert was reported as saved");}catch(android.database.sqlite.SQLiteException expected){}}finally{db.applySnapshot(original);db.close();}}
 @Test public void restoreRollsBackWhenAnyInsertIsIgnored()throws Exception{PaperDb db=new PaperDb(InstrumentationRegistry.getInstrumentation().getTargetContext());JSONObject original=db.snapshot();try{JSONObject existing=db.save("notes",note("before failure"));JSONObject before=db.snapshot(),incoming=new JSONObject(before.toString());JSONArray notes=incoming.getJSONArray("notes");for(int i=0;i<notes.length();i++)if(notes.getJSONObject(i).getString("id").equals(existing.getString("id")))notes.getJSONObject(i).put("title","forced_write_failure");failWrites(db);try{db.applySnapshot(incoming);fail("A partial restore was committed");}catch(android.database.sqlite.SQLiteException expected){}assertEquals(MergePlanner.canonical(before),MergePlanner.canonical(db.snapshot()));}finally{db.applySnapshot(original);db.close();}}
}
